40:[["g040-hero", "ภาพอุปกรณ์/เครื่องมือที่ใช้ในเรื่อง \"เปลี่ยนรหัส Wi-Fi และตั้งค่าเราเตอร์ให้ปลอดภัย\""], ["g040-s1", "ดูที่ฉลากใต้เราเตอร์ เพื่อหา IP หน้าตั้งค่า (มักเป็น 192.168.1.1 แต่ต่างกันตามรุ่น) พร้อมชื่อผู้ใช้และรหัสผ่านเริ่มต้น"], ["g040-s2", "เปิดเบราว์เซอร์ พิมพ์ IP นั้น แล้วล็อกอิน"], ["g040-s3", "เข้าเมนู Wireless หรือ Wi-Fi แล้วเปลี่ยนชื่อเครือข่ายและรหัสผ่าน ให้ยาวอย่างน้อย 12 ตัวและมีตัวอักษรผสมตัวเลข"], ["g040-s4", "เลือกชนิดการเข้ารหัสเป็น WPA2 หรือ WPA3"], ["g040-s5", "เปลี่ยนรหัสเข้าหน้าตั้งค่าเราเตอร์จากค่าเริ่มต้นด้วย"], ["g040-s6", "กดบันทึก แล้วเชื่อมต่ออุปกรณ์ทั้งหมดใหม่ด้วยรหัสใหม่"]],
41:[["g041-hero", "ภาพอาการที่เจอ: หน้าแรกหรือเครื่องมือค้นหาเปลี่ยนไปเอง"], ["g041-s1", "เปิดเมนูส่วนขยาย (Extensions) ของเบราว์เซอร์ แล้วถอดส่วนขยายที่ไม่รู้จักหรือไม่ได้ใช้ออก"], ["g041-s2", "เข้า Settings > Privacy and security > Site settings > Notifications แล้วลบเว็บที่ไม่รู้จักออกจากรายการที่อนุญาต"], ["g041-s3", "ตั้งหน้าแรกและเครื่องมือค้นหาคืนเป็นค่าที่ต้องการ"], ["g041-s4", "ถอนการติดตั้งโปรแกรมแปลก ๆ ที่เพิ่งลงใน Settings > Apps"], ["g041-s5", "สแกนเครื่องด้วย Windows Security แบบ Full scan"], ["g041-s6", "เปลี่ยนรหัสผ่านที่เคยบันทึกในเบราว์เซอร์ หากสงสัยว่าถูกแอบเก็บไป"]],
